using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class CyberOrbShardProbe {
 public static string Run(){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/PixelFX/CyberOrb/Prefabs/CyberOrb_Impact.prefab"));g.hideFlags=HideFlags.HideAndDontSave;var p=g.GetComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);for(int i=0;i<45;i++)p.Simulate(.002f,true,i==0,false);var reports=new List<object>();foreach(var ps in g.GetComponentsInChildren<ParticleSystem>()){var r=ps.GetComponent<ParticleSystemRenderer>();var mesh=new Mesh();r.BakeMesh(mesh,Camera.main,ParticleSystemBakeMeshOptions.BakeRotationAndScale);var uv0=new List<Vector4>();var uv1=new List<Vector4>();mesh.GetUVs(0,uv0);mesh.GetUVs(1,uv1);var a=new ParticleSystem.Particle[ps.particleCount];ps.GetParticles(a);reports.Add(new{ps.name,count=ps.particleCount,renderMode=r.renderMode.ToString(),r.enabled,r.lengthScale,r.velocityScale,material=r.sharedMaterial.name,role=r.sharedMaterial.GetFloat("_Role"),verts=mesh.vertexCount,vertices=mesh.vertices.Take(8).Select(v=>v.ToString()).ToArray(),uv0=uv0.Take(8).Select(v=>v.ToString()).ToArray(),uv1=uv1.Take(8).Select(v=>v.ToString()).ToArray(),colors=mesh.colors32.Take(4).Select(v=>v.ToString()).ToArray(),particles=a.Select(x=>new{pos=x.position.ToString(),size=x.GetCurrentSize(ps),vel=x.totalVelocity.ToString()}).ToArray()});UnityEngine.Object.DestroyImmediate(mesh);}UnityEngine.Object.DestroyImmediate(g);return JsonConvert.SerializeObject(reports);}
}
